--
-- Table structure for table `estilo`
--

DROP TABLE IF EXISTS `estilo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `estilo` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` longtext COLLATE utf8mb4_unicode_ci,
  `maridaje` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fermentacion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estilo_padre_id` int DEFAULT NULL,
  `color` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sabor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `aroma` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `carbonatacion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `origen` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `IDX_E0973A532C05C80E` (`estilo_padre_id`),
  CONSTRAINT `FK_E0973A532C05C80E` FOREIGN KEY (`estilo_padre_id`) REFERENCES `estilo` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
