LOCK TABLES `estilo` WRITE;
/*!40000 ALTER TABLE `estilo` DISABLE KEYS */;
INSERT INTO `estilo` VALUES (1,'Lager','La cerveza Lager es uno de los estilos más populares en el mundo, caracterizada por su fermentación a baja temperatura y su sabor limpio y refrescante. Su proceso de elaboración permite que las levaduras produzcan menos ésteres y compuestos afrutados, lo que resulta en una cerveza más equilibrada y fácil de beber.\r\n\r\nExisten múltiples subestilos dentro de la familia Lager, desde las ligeras Pilsner, hasta las más robustas Bock y Dunkel. Su versatilidad la hace ideal para acompañar una gran variedad de comidas.','Carnes blancas, mariscos, comida picante, quesos suaves...','lager',NULL,'Desde dorado palido hasta ambar oscuro.','Suave, limpio y refrescante, con notas maltosas y un amargor ligero.','Ligero aroma a lupulo, con notas florales y cereal.','Alta, lo que le da un caracter  refrescante y burbujeante.','Alemania / Baviera'),(2,'Pilsner','Originaria de Pilsen, República Checa, en 1842, esta cerveza se caracteriza por su color dorado claro y su sabor equilibrado entre malta y lúpulo. Es refrescante, con un amargor pronunciado debido al lúpulo Saaz, y tiene una espuma blanca duradera','Mariscos, carnes blancas, quesos suaves','lager',1,'Dorado claro','Refrescante, con un amargor pronunciado debido al lúpulo Saaz.','Floral y especiado','Alta','República Checa'),(3,'Dortmunder Export','Creada en Dortmund, Alemania, esta Lager tiene un color dorado intenso y un sabor equilibrado entre malta y lúpulo. Su final es seco y ligeramente amargo, con una carbonatación media.','Embutidos, carnes asadas, platos especiados','lager',1,'Dorado intenso','Equilibrado entre malta y lúpulo, con un final seco','Ligero toque maltoso con notas herbales','Media','Alemania / Dormund'),(4,'Helles','Originaria de Múnich, Alemania, es una Lager dorada pálida con un perfil maltoso y un amargor ligero. Su aroma recuerda al pan y los cereales, y su carbonatación es media-alta','Ensaladas, pollo, comida ligera','lager',1,'Dorodo palido','Suave y maltoso, con un amargor ligero','Notas de pan y cereal','Media-alta','Alemania / Munich'),(5,'Marzen','Tradicionalmente elaborada para el Oktoberfest, esta cerveza ámbar tiene un sabor maltoso con un ligero dulzor y un amargor moderado. Su aroma presenta notas de caramelo y pan tostado.','Carnes asadas, platos alemanes tradicionales.','lager',1,'Ambar','Maltoso con un ligero dulzor y un amargor moderado','Caramelo y pan tostado','Media','Alemania / Baviera'),(6,'Bock','Proveniente de Einbeck, Alemania, es una Lager fuerte con un color ámbar oscuro a marrón. Su sabor es dulce y maltoso, con notas de caramelo y frutos secos.','Guisos, carnes rojas, postres con chocolate','lager',1,'Ámbar oscuro a marrón','Dulce y maltoso, con notas de caramelo y frutos secos.','Tostado y ligeramente afrutado.','Baja','Alemania / Einbeck'),(7,'Dopppelbock','Variante más fuerte de la Bock, con un color marrón oscuro y una graduación alcohólica superior al 7%. Su sabor es intenso y dulce, con notas de caramelo y frutos secos','Platos fuertes, carnes de caza, quesos curados','lager',1,'Marrón oscuro','Intenso y dulce, con notas de caramelo y frutos secos','Maltoso y ligeramente alcohólico','Baja','Alemania / Baviera'),(8,'Schwarzbier','Cerveza negra alemana con un sabor tostado, notas de café y chocolate, pero con un final limpio y ligero. Su carbonatación es media','Carnes ahumadas, postres con cacao, quesos fuertes','lager',1,'Negro','Tostado con notas de café y chocolate, pero con un final limpio','Maltoso con toques de cacao','Media','Alemania'),(9,'Pale Lager','Es una Lager ligera y refrescante, muy popular en marcas comerciales internacionales. Su color es dorado pálido, con un sabor suave y equilibrado entre la malta y el lúpulo. Se caracteriza por su alta carbonatación y su perfil limpio, lo que la hace ideal para climas cálidos.','Aperitivos, comida rápida, mariscos ligeros','lager',1,'Dorado claro','Ligero y refrescante, con un amargor muy suave','Sutiles notas de cereal y lúpulo','Alta','Internacional'),(10,'Ale','Las cervezas Ale se diferencian de las Lager por su fermentación alta, lo que les da un perfil más complejo y aromático. Se fermentan a temperaturas más cálidas (15-25°C), lo que genera ésteres frutales y especiados. Son muy versátiles y abarcan una gran variedad de estilos, desde las ligeras Pale Ale hasta las intensas Barleywine.','Depende del estilo, pero suelen combinar bien con carnes, quesos y platos especiados','ale',NULL,'Varía desde dorado claro hasta negro profundo','Complejo, con notas frutales, especiadas y maltosas','Intenso, con matices de levadura, lúpulo y malta','Media a alta','Europa'),(11,'Pale Ale','La Pale Ale es una de las cervezas más icónicas dentro de la familia Ale. Se caracteriza por su equilibrio entre malta y lúpulo, con un amargor moderado y un cuerpo ligero. Su origen se remonta a Inglaterra, pero ha evolucionado en distintas variantes alrededor del mundo.','Carnes blancas, quesos suaves, comida ligera.','ale',10,'Dorado a cobrizo','Equilibrado entre malta y lúpulo, con notas cítricas y florales','Lúpulo fresco con toques frutales','Media','Inglaterra'),(12,'Indian Pale Ale','La IPA nació en Inglaterra en el siglo XVIII, cuando se aumentó la cantidad de lúpulo para conservar la cerveza en los largos viajes hacia la India. Hoy en día, es uno de los estilos más populares, con múltiples variantes que destacan por su intensidad y complejidad aromática.','Comida picante, carnes asadas, hamburguesas','ale',10,'Dorado a ámbar','Amargor pronunciado con notas cítricas y resinosas','Intenso a lúpulo, con toques tropicales y florales','Media-alta','Inglaterra'),(13,'Amber Ale','La Amber Ale es una cerveza con un perfil más maltoso que la Pale Ale, con notas de caramelo y un amargor equilibrado. Su color rojizo y su cuerpo medio la hacen ideal para acompañar comidas con sabores intensos.','Carnes asadas, platos especiados, quesos curados','ale',10,'Ámbar a rojizo','Maltoso con notas de caramelo y un amargor moderado','Tostado con toques de frutos secos','Media','Estados Unidos'),(14,'Stout','La Stout es una cerveza oscura con un fuerte carácter tostado. Su origen se encuentra en Irlanda, donde se popularizó con marcas como Guinness. Existen múltiples variantes, desde las más secas hasta las más dulces y cremosas.','Postres con chocolate, carnes ahumadas, ostras','ale',10,'Negro profundo','Tostado con notas de café y chocolate','Maltoso con toques de cacao y frutos secos','Baja-media','Irlanda'),(15,'Sour Ale','Las Sour Ales son cervezas ácidas que se fermentan con bacterias y levaduras salvajes. Son refrescantes y complejas, con un perfil afrutado y un toque vinagre. Son muy populares en Bélgica y Alemania, con estilos como Berliner Weisse y Lambic.','Ensaladas, mariscos, quesos frescos','mixta',10,'Amarillo pálido a rojizo','Ácido y afrutado, con notas de frutas y madera','Afrutado con toques de fermentación salvaje','Alta','Bélgica y Alemania'),(16,'Gose','La Gose es una cerveza alemana única, con un perfil ácido y un toque salado. Se elabora con coriandro y sal marina, lo que le da un sabor distintivo. Es ligera y muy refrescante, perfecta para el verano.','Mariscos, comida asiática, quesos frescos','mixta',10,'Amarillo pálido','Ácido y salado, con notas cítricas y especiadas','Afrutado con toques de cilantro y sal marina','Alta','Alemania'),(17,'Belgian Ale','Las Belgian Ales son cervezas con un perfil muy aromático y especiado, gracias a las levaduras belgas. Son complejas y pueden tener una graduación alcohólica elevada. Dentro de esta categoría encontramos estilos como Dubbel, Tripel y Quadrupel.','Carnes blancas, quesos fuertes, platos dulces','ale',10,'Dorado a ámbar','Afrutado y especiado, con notas de levadura belga','Complejo con toques de clavo, plátano y miel','Alta','Belgica'),(18,'Barleywine','El Barleywine, también conocido como \"vino de cebada\", es una de las cervezas más fuertes dentro de la familia Ale. Su alto contenido alcohólico y su perfil maltoso la hacen ideal para beber lentamente y disfrutar de su complejidad. Existen dos variantes principales: English Barleywine → Más maltoso y dulce, con notas de frutos secos y caramelo. American Barleywine → Más lupulado y amargo, con un perfil más agresivo','Carnes de caza, postres con chocolate, quesos curados','ale',10,'Ámbar oscuro a marrón profundo','Intenso y maltoso, con notas de caramelo, frutos secos y un toque alcohólico cálido','Dulce con matices de madera, vainilla y licor','Baja a moderada','Inglaterra'),(19,'English Pale Ale','La English Pale Ale es la versión clásica británica, con un perfil más maltoso y menos lupulado que sus variantes americanas.','Carnes blancas, quesos suaves, comida ligera','ale',11,'Dorado a ámbar','Equilibrado entre malta y lúpulo, con notas de caramelo y pan','Lúpulo terroso con toques florales','Media','Inglaterra'),(20,'American Pale Ale','La APA se caracteriza por el uso de lúpulos americanos, que le dan un perfil más cítrico y aromático.','Hamburguesas, comida picante, tacos','ale',11,'Dorado claro a ámbar','Amargor moderado con notas cítricas y frutales','Lúpulo fresco con matices tropicales','Media-alta','Estados Unidos'),(21,'Belgian Pale Ale','La Belgian Pale Ale tiene un perfil más especiado y afrutado debido a las levaduras belgas.','Carnes blancas, quesos fuertes, platos dulces','ale',11,'Ámbar claro','Maltoso con notas especiadas y afrutadas','Levadura belga con toques de miel y frutas','Media','Belgica'),(22,'Strong Pale Ale','Las Strong Pale Ale son versiones más alcohólicas y robustas de las Pale Ale tradicionales.','Carnes asadas, platos especiados, quesos curados','ale',11,'Dorado intenso','Más intenso que una Pale Ale estándar, con mayor presencia de malta y lúpulo','Lúpulo marcado con notas de caramelo y frutas maduras','Media','Internacional'),(23,'Extra Special Bitter','El ESB es una versión más fuerte y maltosa de la clásica Bitter inglesa. Aunque su nombre sugiere un amargor intenso, en realidad es bastante equilibrada, con un perfil maltoso y un toque de lúpulo británico.','Carnes asadas, platos especiados, quesos curados','ale',11,'Ámbar a cobrizo','Equilibrado entre malta y lúpulo, con notas de caramelo y frutos secos','Lúpulo terroso con toques florales y maltosos','Media','Inglaterra'),(24,'DDH Pale Ale','La DDH Pale Ale se caracteriza por el proceso de Double Dry Hopping (DDH), que consiste en añadir lúpulo en dos etapas durante la fermentación. Esto potencia los aromas y sabores sin aumentar el amargor.','Comida picante, tacos, sushi, quesos suaves','ale',11,'Dorado claro a ámbar','Intensamente lupulado, con notas cítricas y tropicales','Explosión de lúpulo fresco con matices frutales y herbales','Media-alta','Internacional'),(25,'Session Pale Ale','Las Session Pale Ale están diseñadas para ser fáciles de beber, con menor contenido alcohólico pero manteniendo el carácter lupulado. Son ideales para largas sesiones sin afectar la resistencia del bebedor.','Aperitivos, comida rápida, mariscos ligeros','ale',11,'Dorado claro','Ligero y refrescante, con un amargor moderado','Lúpulo fresco con toques cítricos y florales','Alta','Estados Unidos'),(26,'American Amber Ale','La American Amber Ale es una versión más maltosa de la American Pale Ale, con un color más oscuro y un perfil de caramelo más pronunciado.','Carnes asadas, platos especiados, quesos curados','ale',13,'Ámbar a cobrizo','Maltoso con notas de caramelo y un amargor moderado','Lúpulo fresco con toques cítricos y resinosos','Media','Estados Unidos'),(27,'Red Ale','La Red Ale es una cerveza de fermentación alta con un color rojizo característico, resultado del uso de maltas tostadas especiales. Su perfil es equilibrado entre dulzor y amargor, con notas de caramelo y frutos secos. En algunos casos, puede tener un toque lupulado más pronunciado, especialmente en versiones americanas.','Carnes asadas, quesos curados, platos especiados','ale',13,'Rojo cobrizo a rojo oscuro','Dulce y maltoso, con notas de caramelo y un amargor suave','Tostado con toques de frutos secos y bizcocho','Media','Irlanda'),(28,'Altbier','La Altbier es una cerveza alemana de fermentación alta, pero con un perfil limpio similar a una Lager, gracias a su fermentación a temperaturas más bajas.','Embutidos, carnes ahumadas, quesos curados','ale',13,'Ámbar oscuro','Equilibrado entre malta y lúpulo, con un final seco','Maltoso con toques especiados','Media','Alemania'),(29,'Scottish Export Ale','La Scottish Export Ale es una versión más fuerte de las cervezas escocesas tradicionales, con un perfil maltoso y un amargor suave.','Carnes de caza, platos especiados, quesos fuertes','ale',13,'Ámbar oscuro','Maltoso con notas de caramelo y frutos secos','Tostado con toques de pan y miel','Media','Escocia'),(30,'Brown Ale','La Brown Ale es una cerveza de fermentación alta con un perfil maltoso y tostado, pero sin los sabores intensamente quemados de una Porter. Existen variantes como la English Brown Ale y la American Brown Ale, que pueden diferir en dulzor y amargor.','Carnes asadas, platos especiados, quesos curados','ale',13,'Ámbar oscuro a marrón','Maltoso con notas de caramelo, frutos secos y chocolate ligero','Tostado con toques de nuez y toffee','Media','Inglaterra'),(31,'American Ipa','La American IPA es una evolución de la IPA inglesa, con un perfil más lupulado y aromático gracias al uso de lúpulos americanos. Se caracteriza por su frescura y su equilibrio entre amargor y notas frutales.','Comida picante, carnes asadas, hamburguesas','ale',12,'Dorado claro a ámbar','Amargor pronunciado con notas cítricas y resinosas','Lúpulo fresco con matices tropicales y florales','Media-alta','Estados Unidos'),(32,'New England IPA','La NEIPA se caracteriza por su turbidez y su textura sedosa, con un perfil de lúpulo más afrutado y menos amargo que otras IPAs. Es una de las variantes más populares en la actualidad.','Sushi, mariscos, comida asiática','ale',12,'Dorado turbio','Suave y afrutado, con un amargor moderado','Explosión de lúpulo con notas tropicales y cítricas','Media','Estados Unidos'),(33,'Doble NEIPA',NULL,NULL,'ale',12,NULL,NULL,NULL,NULL,'Internacional'),(34,'Session IPA','La Session IPA es una versión más ligera de la IPA tradicional, diseñada para ser fácil de beber sin perder el carácter lupulado. Su menor contenido alcohólico permite disfrutarla en sesiones prolongadas sin afectar la resistencia del bebedor.','Aperitivos, comida rápida, mariscos ligeros','ale',12,'Dorado claro','Ligero y refrescante, con un amargor moderado','Lúpulo fresco con notas cítricas y frutales','Media','Estados Unidos'),(35,'West Cost','La West Coast IPA es una IPA clásica de la costa oeste de EE.UU., caracterizada por su alto amargor y su perfil lupulado agresivo con notas resinosas y cítricas.','Carnes asadas, comida picante, quesos curados','ale',12,'Dorado intenso','Amargor pronunciado con notas resinosas y cítricas','Lúpulo intenso con matices de pino y frutas tropicales','Media','Estados Unidos'),(36,'Black IPA','La Black IPA combina el perfil lupulado de una IPA con las maltas oscuras de una Porter, creando una cerveza con notas tostadas y un amargor potente.','Carnes ahumadas, platos especiados, quesos fuertes','ale',12,'Marrón oscuro a negro','Amargor pronunciado con notas tostadas y resinosas','Lúpulo intenso con matices de café y chocolate','Media','Estados Unidos'),(37,'Triple IPA','La Triple IPA es una versión extrema de la IPA, con altísima carga de lúpulo y mayor contenido alcohólico, ofreciendo una experiencia intensa y compleja.','Carnes grasas, platos especiados, quesos curados','ale',12,'Dorado intenso','Amargor extremo con notas frutales y resinosas','Explosión de lúpulo con matices tropicales y cítricos','Media','Estados Unidos'),(38,'Triple NEIPA','La Triple NEIPA es una versión extrema de la New England IPA, con una mayor carga de lúpulo y un cuerpo más robusto. Su textura sedosa y su turbidez característica provienen del uso de avena y trigo, mientras que el triple dry hopping potencia los aromas sin aumentar el amargor.','Carnes grasas, platos especiados, quesos curados','ale',12,'Dorado turbio','Intenso y afrutado, con un amargor moderado','Explosión de lúpulo con notas tropicales y cítricas','Media','Estados Unidos'),(39,'Ron','Elaborado a partir de la caña de azúcar, el Ron se fermenta y destila antes de pasar por un proceso de añejamiento en barricas de roble. Su perfil varía desde ligero y seco hasta más dulce y envejecido.','Chocolate, postres, carnes ahumadas',NULL,NULL,NULL,'Dulce y especiado, con notas de vainilla y caramelo','Frutal y tostado, con matices de madera',NULL,'Caribe'),(40,'Vodka','Destilado a partir de cereales o patata, el Vodka se somete a múltiples filtrados para obtener una pureza excepcional. Su perfil limpio lo hace ideal para cócteles y mezclas.','Caviar, encurtidos, cócteles',NULL,NULL,NULL,'Neutro y limpio, con un final suave','Ligero y fresco',NULL,'Rusio / Polonia'),(41,'Ginebra','Destilado con bayas de enebro y botánicos, la Ginebra ofrece un perfil aromático único, variando de seca y cítrica a más afrutada y compleja.','Tónica, cítricos, mariscos',NULL,NULL,NULL,'Herbal y especiado, con notas cítricas','Enebro predominante con matices florales',NULL,'Reino Unido / Países Bajos'),(42,'Whiskey','Destilado a partir de cebada, maíz o centeno, el Whiskey se envejece en barricas de roble, desarrollando su riqueza aromática y sabor robusto. Existen variantes como Scotch, Bourbon y Rye.','Chocolate negro, frutos secos, carnes rojas',NULL,NULL,NULL,'Complejo y profundo, con notas de madera y vainilla','Ahumado y especiado',NULL,'Escocia / Irlanda');
/*!40000 ALTER TABLE `estilo` ENABLE KEYS */;
