/*!40000 ALTER TABLE `fabricante` DISABLE KEYS */;
INSERT INTO `fabricante` VALUES (1,'Mahou','España/Madrid','Fundada en 1890 por la familia Mahou, esta cervecera madrileña se ha consolidado como líder en el mercado español, destacando por su innovación y compromiso con la calidad.','mahou.jpg'),(2,'Waldi','Alemania/Colonia','Cervecera artesanal emergente de Colonia-Sülz, reconocida por su enfoque creativo y moderno en la elaboración de cervezas. Con una estética distintiva inspirada en perros salchicha, combina tradición y modernidad, ofreciendo desde Kölsch sin filtrar hasta DDH NEIPAs.','waldiBalboa.jpg'),(3,'Hijos de Rivera','España / La Coruña','Desde 1906, esta empresa familiar gallega ha mantenido su independencia, ofreciendo cervezas de alta calidad y apostando por la sostenibilidad y la innovación.','hijosDeRivera.jpg'),(4,'Paulaner Brauerei GmbH','Alemania / Múnich','Con raíces que se remontan a 1634, esta cervecera bávara es reconocida por sus tradicionales cervezas de trigo y su participación en el Oktoberfest.','paulaner.jpg'),(5,'Guinness Brewery','Irlanda / Dublín','Establecida en 1759, Guinness es famosa por su icónica stout y su rica historia, siendo una de las cervezas más reconocidas a nivel mundial.','guinness.jpg'),(6,'Heineken N.V.','Países Bajos / Ámsterdam','Desde 1864, Heineken ha crecido hasta convertirse en una de las cerveceras más grandes del mundo, conocida por su lager de sabor distintivo y su presencia global.','heineken.jpg'),(7,'Arpus Brewing Co.','Letonia / Riga','Microcervecera independiente fundada en 2017 por entusiastas del craft beer en Letonia. El nombre Ārpus —que significa fuera, más allá, sin límites— representa su filosofía: elaborar cervezas fuera de lo convencional, alejadas de las lagers industriales. Especializados en ales intensamente lupuladas, sours afrutadas y stouts imperiales audaces. Reconocida como la cervecera número uno de los Estados Bálticos en Untappd.','arpus.jpg'),(8,'Soma Beer','España / Girona','Cervecera artesanal independiente fundada en 2016, especializada en estilos extra lupulados como NEIPAs y subgéneros de IPAs. En constante búsqueda de la cerveza perfecta, elaboran ediciones limitadas que les permiten experimentar semanalmente con diferentes recetas y lúpulos.','soma.jpg'),(9,'Basqueland Brewing','España / Guipuzkoa/ Hernani','Cervecera artesanal fundada en 2015 en el corazón del País Vasco. Reconocida por fusionar la innovación del craft beer moderno con los sabores tradicionales vascos, ha sido galardonada como Mejor Cervecera de España en múltiples ocasiones.','basqueland.jpg'),(10,'Garage Beer Co','España / Barcelona','Conocida por sus cervezas modernas y experimentales, Garage Beer Co. es un referente en la escena craft barcelonesa.','garage.jpg'),(11,'Attik Brewing','España / Málaga','Cervecera nómada malagueña fundada por dos amigos de la infancia, Jaime y Umeed, que comenzaron elaborando cerveza en el ático de una casa. Desde 2018, han producido más de 100 cervezas, destacando en estilos lupulados e Imperial Stouts. Reconocida como la mejor cervecera en 2022 por la Mediterranean Cup y galardonada en varias ediciones del Barcelona Beer Challenge.','attik.jpg'),(12,'Nepomucen Browar','Polonia / Szkaradowo','Fundado en 2014 por los hermanos Piotr y Mariusz Musielak en una antigua panadería de Szkaradowo, Nepomucen es un referente del craft polaco. Destaca por sus IPAs modernas y cervezas con ingredientes locales como agujas de pino y abeto. Con más de 150,000 litros mensuales y colaboraciones internacionales, mantiene su esencia artesanal y creatividad.','nepomucen.jpg'),(13,'Naparbier','España / Pamplona','undada en 2009 por un grupo de amigos desempleados, Naparbier se ha convertido en una de las cerveceras artesanales más reconocidas de España, destacando por su calidad y colaboraciones internacionales.','naparbier.jpg'),(14,'Funky Fluid','Polonia / Varsovia','Funky Fluid es una cervecería artesanal polaca conocida por sus cervezas innovadoras y de alta calidad, en particular sus IPAs con lúpulo y sus sours con notas afrutadas. Ubicada en Varsovia, se fundó en 2018 y rápidamente ha alcanzado reconocimiento internacional, incluyendo su nombramiento como la tercera mejor cervecería nueva del mundo por Ratebeer en 2019.','funkyFluid.jpg'),(15,'Sapporo Breweries Ltd','Japón / Sapporo','Es la marca de cerveza más antigua de Japón y la marca insignia de Sapporo Holdings. La historia de la compañía comienza con Seibei Nakagawa, el primer maestro cervecero de Japón formado en Alemania, quien fundó la cervecería Sapporo en 1876. El éxito de Sapporo se ha basado en el compromiso con las técnicas cerveceras tradicionales y la fusión de influencias orientales y occidentales, con un enfoque en la calidad y la innovación.','sapporo.jpg'),(16,'Carlow Brewing Company','Irlanda / Carlow','Fundada en 1996, Carlow Brewing Company es una de las cerveceras artesanales más reconocidas de Irlanda. Bajo la marca O\'Hara\'s, producen cervezas tradicionales irlandesas con un enfoque en calidad y autenticidad, incluyendo Irish Red Ale, Irish Stout y Pale Ale. ✅','carlow.jpg'),(17,'Brew Dog','Escocia / Ellon','BrewDog es una cervecera escocesa fundada en 2007, famosa por sus IPAs innovadoras y cervezas artesanales con un enfoque moderno y rebelde.','brewdog.jpg'),(18,'Northern Monk','Inglaterra / Leeds','Fundada en 2013, Northern Monk combina la tradición monástica cervecera con un enfoque moderno e innovador. Su filosofía se basa en la creatividad, la comunidad y la colaboración, produciendo cervezas de alta calidad con ingredientes cuidadosamente seleccionados.','northernMonk.jpg'),(19,'San Frutos','España / Segovia','Somos una cervecera artesana, independiente y familiar ubicada en Hontoria, Segovia, a los pies de la sierra de Guadarrama,Desde 2013 hemos apostado por la elaboración de cervezas artesanas, equilibradas y de calidad.','SanFrutos.png'),(20,'Brouwerij Huyghe','Belgica / Melle','Fundada en 1906, Brouwerij Huyghe es una cervecera belga reconocida por su icónica marca Delirium, famosa por su elefante rosa y sus cervezas de alta fermentación con sabores complejos y distintivos.','BrouwerijHuyghe.jpg'),(21,'Coca Cola','Estados Unidos / Atlanta','Fundada en 1886, The Coca-Cola Company es una de las mayores empresas de bebidas del mundo, con una amplia gama de refrescos, aguas y zumos. Su icónica Coca-Cola es la bebida más vendida globalmente.','Cocacola.png'),(22,'Schweppes','Suiza / Reino Unido','Creada en 1783 por Johann Jacob Schweppe, Schweppes es pionera en bebidas carbonatadas. Su tónica es un referente en mixología y refrescos premium.','Scheweppes.png'),(23,'Minute Maid','Estados Unidos / Texas','Filial de Coca-Cola desde 1960, Minute Maid es líder en zumos y néctares de fruta, ofreciendo opciones sin azúcares añadidos y con ingredientes naturales.','minuteMaid.png'),(24,'Bodegas Cepa 21','España / Valladolid','Fundada por la familia Moro, Cepa 21 combina tradición y modernidad en la elaboración de vinos de alta calidad en la Ribera del Duero.','BodegasCepa21.jpg'),(25,'Bodegas Manzanos','España / La Rioja','Con más de 130 años de historia, Bodegas Manzanos es una de las bodegas más emblemáticas de Rioja, elaborando vinos con identidad y tradición.','BodegasManzanos.jpg'),(26,'Bodega Matsu','España / Zamora','Matsu es una bodega que rinde homenaje a la tradición vitivinícola de Toro, con vinos que reflejan la fuerza y carácter de la región.','BodegaMatsu.jpg'),(27,'Bodega Javier Sanz Viticultor','España / Valladolid','Con más de 40 años de historia, Javier Sanz elabora vinos con identidad propia, respetando la tradición y el carácter único del Verdejo.','BodegaJavierSanzViticultor.jpg'),(28,'Havana Club','Cuba','Fundada en 1934, Havana Club es la marca de ron más emblemática de Cuba, con una tradición de elaboración artesanal y envejecimiento en barricas de roble.','HavanaClub.png'),(29,'Ron Barcelo','República Dominicana','Desde 1930, Ron Barceló ha sido un referente en la producción de rones dominicanos, con un enfoque en calidad y envejecimiento natural.','RonBarcelo.png'),(30,'Absolut','Suecia','Fundada en 1879, Absolut es una de las marcas de vodka más reconocidas, con un proceso de destilación continua que garantiza pureza y suavidad.','Absolut.png'),(31,'Belvedere','Polonia','Belvedere es un vodka de lujo producido en Polonia desde 1993, utilizando centeno de alta calidad y un proceso de destilación tradicional.','Belvedere.png'),(32,'Tanqueray','Inglaterra','Fundada en 1830, Tanqueray es una de las ginebras más icónicas, con un proceso de destilación que resalta el enebro y los cítricos.','Tanqueray.png'),(33,'Bombay Sapphire','Inglaterra','Bombay Sapphire es una ginebra premium con un proceso de infusión único, utilizando 10 botánicos cuidadosamente seleccionados.','Bombay.png'),(34,'Jameson','Irlanda','Fundada en 1780, Jameson es la marca de whiskey irlandés más reconocida, con un proceso de triple destilación que garantiza suavidad y equilibrio.','Jameson.png'),(35,'Glenfiddich','Escocia','Glenfiddich es una de las destilerías más prestigiosas de Escocia, especializada en whiskies single malt con envejecimiento en barricas de roble.','Glenfiddich.png');
/*!40000 ALTER TABLE `fabricante` ENABLE KEYS */;
UNLOCK TABLES;

